  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment)
  }

  /** helper function to set the values of all input ports.
   * @param image_feedback payload for data port image_feedback
   */
  def put_concrete_inputs(image_feedback : EIT_Acquisition_Supervisor.ImageFeedback.Type): Unit = {
    put_image_feedback(image_feedback)
  }


  /** helper function to check ImageResultAssessment_acquisition_process_image_result_assessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param image_result_facts method that will be called with the value of the outgoing data
   *        port 'image_result_facts'.
   */
  def check_concrete_output(image_result_facts: EIT_Acquisition_Supervisor.ImageResultFacts.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val image_result_factsValue: EIT_Acquisition_Supervisor.ImageResultFacts.Type = get_image_result_facts().get
    if(!image_result_facts(image_result_factsValue)) {
      testFailures = testFailures :+ st"'image_result_facts' did not match expected: value of the outgoing data port is ${image_result_factsValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_image_feedback(value : EIT_Acquisition_Supervisor.ImageFeedback.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment.operational_api.image_feedback_Id, EIT_Acquisition_Supervisor.ImageFeedback_Payload(value))
  }

  // getter for out DataPort
  def get_image_result_facts(): Option[EIT_Acquisition_Supervisor.ImageResultFacts.Type] = {
    val value: Option[EIT_Acquisition_Supervisor.ImageResultFacts.Type] = get_image_result_facts_payload() match {
      case Some(EIT_Acquisition_Supervisor.ImageResultFacts_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port image_result_facts.  Expecting 'EIT_Acquisition_Supervisor.ImageResultFacts_Payload' but received ${v}")
      case _ => None[EIT_Acquisition_Supervisor.ImageResultFacts.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_image_result_facts_payload(): Option[EIT_Acquisition_Supervisor.ImageResultFacts_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment.initialization_api.image_result_facts_Id).asInstanceOf[Option[EIT_Acquisition_Supervisor.ImageResultFacts_Payload]]
